def transform(grid):
    n = len(grid)
    vals = [row[0] for row in grid]
    anchors = [(i, v) for i, v in enumerate(vals) if v != 0]

    # Find the shortest period consistent with every nonzero row.
    for p in range(1, n + 1):
        ok = True
        assigned = {}
        for i, v in anchors:
            r = i % p
            if r in assigned and assigned[r] != v:
                ok = False
                break
            assigned[r] = v
        if ok:
            break

    # Fill unconstrained positions by carrying the next known color
    # around the periodic sequence.
    pattern = [None] * p
    for i, v in anchors:
        pattern[i % p] = v
    known = [i for i, v in enumerate(pattern) if v is not None]
    for r in range(p):
        if pattern[r] is None:
            nxt = min(known, key=lambda k: (k - r) % p)
            pattern[r] = pattern[nxt]

    return [[pattern[i % p]] * len(grid[0]) for i in range(n)]
